'use strict';

// MODULES //

var isnanf = require( '@stdlib/math/base/assert/is-nanf' );
var f32 = require( '@stdlib/number/float64/base/to-float32' );
var toWordf = require( '@stdlib/number/float32/base/to-word' );
var fromWordf = require( '@stdlib/number/float32/base/from-word' );
var ABS_MASK = require( '@stdlib/constants/float32/abs-mask' );
var FLOAT32_EXPONENT_BIAS = require( '@stdlib/constants/float32/exponent-bias' );
var FLOAT32_SIGNIFICAND_MASK = require( '@stdlib/constants/float32/significand-mask' );
var FLOAT32_EXPONENT_MASK = require( '@stdlib/constants/float32/exponent-mask' );
var NINF = require( '@stdlib/constants/float32/ninf' );
var kernelLog1pf = require( '@stdlib/math/base/special/kernel-log1pf' );


// VARIABLES //

// 1.1754943508222875e-38 => 0 00000001 00000000000000000000000 => 0x00800000 = 8388608
var MIN_NORM_WORD = 0x00800000|0; // asm type annotation

// 1 => 0 01111111 00000000000000000000000 => 0x3f800000 = 1065353216
var ONE_WORD = 0x3f800000|0; // asm type annotation

// Mask to clear lower 12 mantissa bits:
var TRUNC_MASK = 0xfffff000|0; // asm type annotation

var TWO25 = f32( 3.3554432000e+07 );   // 0x4c000000
var IVLN2HI = f32( 1.4428710938e+00 ); // 0x3fb8b000
var IVLN2LO = f32( -1.7605285393e-04 ); // 0xb9389ad4


// MAIN //

/**
* Evaluates the binary logarithm (base two) of a single-precision floating-point number.
*
* @param {NonNegativeNumber} x - input value
* @returns {number} function value
*
* @example
* var v = log2f( 4.0 );
* // returns 2.0
*
* @example
* var v = log2f( 8.0 );
* // returns 3.0
*
* @example
* var v = log2f( 0.0 );
* // returns -Infinity
*
* @example
* var v = log2f( Infinity );
* // returns Infinity
*
* @example
* var v = log2f( NaN );
* // returns NaN
*
* @example
* var v = log2f( -4.0 );
* // returns NaN
*/
function log2f( x ) {
	var valHi;
	var valLo;
	var hfsq;
	var hi;
	var hx;
	var lo;
	var f;
	var R;
	var w;
	var y;
	var i;
	var k;

	if ( isnanf( x ) || x < 0.0 ) {
		return NaN;
	}
	x = f32( x );
	hx = toWordf( f32( x ) ) | 0; // asm type annotation
	k = 0|0; // asm type annotation
	if ( hx < MIN_NORM_WORD  ) {
		// Case: x < 2**-126
		if ( ( hx & ABS_MASK ) === 0 ) {
			return NINF;
		}
		k -= 25|0; // asm type annotation

		// Subnormal number, scale up x:
		x = f32( x * TWO25 );
		hx = toWordf( x ) | 0;
	}
	if ( hx >= FLOAT32_EXPONENT_MASK ) {
		return f32( x + x );
	}
	// Case: log(1) = +0
	if ( hx === ONE_WORD  ) {
		return 0.0;
	}
	k += ( ( hx >> 23 ) - FLOAT32_EXPONENT_BIAS ) | 0; // asm type annotation
	hx &= FLOAT32_SIGNIFICAND_MASK;
	i = ( ( hx+0x4afb0d ) & MIN_NORM_WORD  )|0; // asm type annotation

	// Normalize x or x/2...
	x = fromWordf( hx | ( i ^ ONE_WORD ) );
	k += ( ( i >> 23 ) | 0 ); // asm type annotation
	y = k;
	f = f32( x - f32( 1.0 ) );
	hfsq = f32( f32( 0.5 ) * f32( f * f ) );
	R = kernelLog1pf( f );
	hi = f32( f - hfsq );
	hx = toWordf( hi ) | 0; // asm type annotation
	hi = fromWordf( hx & TRUNC_MASK);
	lo = f32( f32( f32(f - hi ) - hfsq) + R );
	valHi = hi * IVLN2HI;
	valLo = ( ( lo + hi ) * IVLN2LO ) + ( lo * IVLN2HI );

	w = y + valHi;
	valLo += ( y - w ) + valHi;
	valHi = w;

	return valLo + valHi;
}


// EXPORTS //

module.exports = log2f;
